package com.dekhocampus.platform.observability;
import java.io.IOException; import java.util.UUID; import org.slf4j.MDC; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import jakarta.servlet.FilterChain; import jakarta.servlet.ServletException; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse;
@Component public class RequestIdFilter extends OncePerRequestFilter { @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{var supplied=req.getHeader("X-Request-Id");var id=supplied!=null&&supplied.matches("[A-Za-z0-9._-]{8,100}")?supplied:UUID.randomUUID().toString();MDC.put("requestId",id);res.setHeader("X-Request-Id",id);try{chain.doFilter(req,res);}finally{MDC.remove("requestId");}} }
